    ps.println ("public class Calculate");
    ps.println ("extends Object");
    ps.println ("implements java.io.Serializable");
    ps.println ("{");
    ps.println ("  ");
    ps.println ("  private Paint g2d;");
    ps.println ("  private char letter;");
    ps.println ("  private Rect rect;");
    ps.println ("  ");
    ps.println ("  private int pxcoord=0;");
    ps.println ("  private int pycoord=0;");
    ps.println ("  ");
    ps.println ("  public Calculate ()");
    ps.println ("  {");
    ps.println ("    super ();");
    ps.println ("  }");
    ps.println ("  ");
    ps.println ("  public Calculate (Paint xg2d, char xletter, Rect xrect)");
    ps.println ("  {");
    ps.println ("    super ();");
    ps.println ("    ");
    ps.println ("    this.g2d=xg2d;");
    ps.println ("    this.letter=xletter;");
    ps.println ("    this.rect=xrect;");
