    ps.println ("    int w=bounds.width ();");
    ps.println ("    int h=bounds.height ();");
    ps.println ("    ");
    ps.println ("    int wmiddle=(w/2);");
    ps.println ("    int hmiddle=(h/2);");
    ps.println ("    int smiddle=((rect.right)-(rect.left))/2;");
    ps.println ("    ");
    ps.println ("    pxcoord=((rect.left)+(smiddle-wmiddle));");
    ps.println ("    ");
    ps.println ("    int kmiddle=((rect.bottom)-(rect.top))/2;");
    ps.println ("    ");
    ps.println ("    if (module == 0)");
    ps.println ("    {");
    ps.println ("      pycoord=((rect.top)+(kmiddle)-(hmiddle));");
    ps.println ("    }");
    ps.println ("    else if (module == 1)");
    ps.println ("    {");
    ps.println ("      pycoord=((rect.top)+(kmiddle)+(hmiddle));");
    ps.println ("    }");
    ps.println ("    else");
    ps.println ("    {");
    ps.println ("      pycoord=0;");
    ps.println ("    }");
    ps.println ("    ");
