    ps.println ("  // Harf kontrol metodu");
    ps.println ("  private void checkLetter(char pressedChar)");
    ps.println ("  {");
    ps.println ("    if (sprite == null) return;");
    ps.println ("    ");
    ps.println ("    String currentWord = sprite.getPT();");
    ps.println ("    ");
    ps.println ("    // Generate sınıfındaki harika normalizasyon metodunu kullan");
    ps.println ("    String normalizedWord = Generate.replaceActualWord(currentWord).toUpperCase();");
    ps.println ("    String normalizedChar = Generate.replaceActualWord(String.valueOf(pressedChar)).toUpperCase();");
    ps.println ("    ");
    ps.println ("    // foundLetters dizisini sprite'tan al veya oluştur");
    ps.println ("    boolean[] foundLetters = sprite.getFoundLetters();");
    ps.println ("    if (foundLetters == null) {");
    ps.println ("      foundLetters = new boolean[normalizedWord.length()];");
    ps.println ("      sprite.setFoundLetters(foundLetters);");
    ps.println ("    }");
    ps.println ("    ");
    ps.println ("    if (normalizedWord.contains(normalizedChar))");
    ps.println ("    {");
    ps.println ("      // Harfi bulundu olarak işaretle");
    ps.println ("      for (int j = 0; j < normalizedWord.length(); j++)");
    ps.println ("      {");
    ps.println ("        if (normalizedWord.charAt(j) == normalizedChar.charAt(0))");
    ps.println ("        {");
    ps.println ("          foundLetters[j] = true;");
    ps.println ("        }");
    ps.println ("      }");
    ps.println ("      ");
    ps.println ("      // Tüm harfler bulundu mu kontrol et");
    ps.println ("      boolean allFound = true;");
    ps.println ("      for (int j = 0; j < normalizedWord.length(); j++)");
    ps.println ("      {");
    ps.println ("        if (!foundLetters[j])");
    ps.println ("        {");
    ps.println ("          allFound = false;");
    ps.println ("          break;");
    ps.println ("        }");
    ps.println ("      }");
    ps.println ("      ");
    ps.println ("      if (allFound)");
    ps.println ("      {");
    ps.println ("        // Tam kelime doğru - 50 puan + silah sesi");
    ps.println ("        playGun();");
    ps.println ("        score += 50;");
    ps.println ("        // Sonraki kelimeye geç");
    ps.println ("        sprite.playSound();");
    ps.println ("        sprite.setEnd(true); // Mevcut kelimeyi bitir");
    ps.println ("      }");
    ps.println ("      else");
    ps.println ("      {");
    ps.println ("        // Sadece harf doğru - 5 puan");
    ps.println ("        score += 5;");
    ps.println ("      }");
    ps.println ("    }");
    ps.println ("    else");
    ps.println ("    {");
    ps.println ("      // Yanlış harf");
    ps.println ("      playError();");
    ps.println ("      score -= 5;");
    ps.println ("      lives--;");
    ps.println ("      ");
    ps.println ("      if (lives <= CERO)");
    ps.println ("      {");
    ps.println ("        isEnd = true;");
    ps.println ("        drawx ();");
    ps.println ("      }");
    ps.println ("    }");
    ps.println ("  }");
    
    ps.println ("  ");
    ps.println ("  public final void setSprites ()");
