    ps.println ("  final");
    ps.println ("  private static void copy (File sx, File dx)");
    ps.println ("  throws IOException");
    ps.println ("  {");
    ps.println ("	  InputStream fis=new FileInputStream (sx);");
    ps.println ("	  ");
    ps.println ("	  OutputStream fos=new FileOutputStream (dx);");
    ps.println ("	  ");
    ps.println ("	  int MAX=8*1024;");
    ps.println ("	  ");
    ps.println ("	  byte [] bytes=new  byte [MAX];");
    ps.println ("	  ");
    ps.println ("	  final int CERO=0x0000;");
    ps.println ("	  ");
    ps.println ("	  int c=-1;");
    ps.println ("	  ");
    ps.println ("	  while ( (c=fis.read (bytes, CERO, MAX)) != -1)");
    ps.println ("	  {");
    ps.println ("		  fos.write (bytes, CERO, c);");
    ps.println ("	  }");
    ps.println ("	  ");
    ps.println ("	  fis.close ();");
    ps.println ("	  ");
    ps.println ("	  fos.flush ();");
    ps.println ("	  fos.close ();");
    ps.println ("	  ");
    ps.println ("	  return;");
    ps.println ("  }");
